import { useEffect, useState } from "react";
import { getAppInfo } from "../integrations/getAppInfo.js";
const useAppInfo = ()=>{
    const [appInfo, setAppInfo] = useState({});
    useEffect(()=>{
        const updateDomInfo = (info)=>{
            if (info.name) {
                document.title = info.name;
                const meta = document.querySelector("meta[property='og:title']");
                if (meta) meta.content = info.name;
            }
            if (info.avatar) {
                let link = document.querySelector("link[rel~='icon']");
                if (!link) {
                    link = document.createElement('link');
                    link.rel = 'icon';
                    document.head.appendChild(link);
                }
                link.href = info.avatar;
                const meta = document.querySelector("meta[property='og:image']");
                if (meta) meta.content = info.avatar;
            }
            if (info.description) {
                const meta = document.querySelector("meta[property='og:description']");
                if (meta) meta.content = info.description;
                const metaDom = document.querySelector("meta[name='description']");
                if (metaDom) metaDom.content = info.description;
            }
        };
        const handleMetaInfoChanged = async (info, refresh = true)=>{
            if (!info) info = await getAppInfo(refresh);
            updateDomInfo(info);
            setAppInfo((prev)=>({
                    ...prev,
                    ...info
                }));
        };
        handleMetaInfoChanged(null, false);
        const onUpdate = (e)=>{
            const info = e.detail;
            handleMetaInfoChanged(info);
        };
        window.addEventListener('MiaoDaMetaInfoChanged', onUpdate);
        return ()=>{
            window.removeEventListener('MiaoDaMetaInfoChanged', onUpdate);
        };
    }, []);
    return {
        ...appInfo,
        appName: appInfo.name,
        appLogo: appInfo.avatar
    };
};
export { useAppInfo };
